// ============================================
// HMAC VERIFICATION - RFC-099
// ============================================

const crypto = require('crypto');

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Get HMAC signature from header
const signatureHeader = headers['x-webhook-signature'] || headers['X-Webhook-Signature'] || '';
const providedSignature = signatureHeader.replace('sha256=', '');

// Get secret from env
const secret = process.env.N8N_RAG_WEBHOOK_SECRET;

if (!secret) {
  return {
    hmac_valid: false,
    error: 'N8N_RAG_WEBHOOK_SECRET not configured',
    http_code: 500
  };
}

if (!signatureHeader) {
  return {
    hmac_valid: false,
    error: 'Missing X-Webhook-Signature header',
    http_code: 401
  };
}

// Compute HMAC-SHA256
// Body should be the raw JSON string
const bodyString = JSON.stringify(body, null, 0); // Compact JSON
const hmac = crypto.createHmac('sha256', secret);
hmac.update(bodyString, 'utf8');
const computedSignature = hmac.digest('hex');

// Timing-safe comparison
const isValid = crypto.timingSafeEqual(
  Buffer.from(providedSignature, 'hex'),
  Buffer.from(computedSignature, 'hex')
);

if (!isValid) {
  return {
    hmac_valid: false,
    error: 'Invalid HMAC signature',
    http_code: 401,
    debug: {
      provided: providedSignature.substring(0, 16) + '...',
      computed: computedSignature.substring(0, 16) + '...'
    }
  };
}

return {
  hmac_valid: true,
  body: body,
  headers: headers
};

// ============================================
// VALIDATION PAYLOAD - RFC-099 §3.2
// ============================================

const body = $('Verify HMAC').item.json.body;
const errors = [];

// Required fields
const sourceId = body.source_id;
const tenantId = body.tenant_id;
const guildId = body.guild_id;
const botId = body.bot_id;
const active = body.active;
const fileType = body.file_type;

// File source (b2_file_key OR url)
const b2FileKey = body.b2_file_key || null;
const url = body.url || null;

// Optional fields
const extractionMethod = body.extraction_method || 'auto';
const title = body.title || null;
const lang = body.lang || null;
const callbackUrls = body.callback_urls || {};
const qdrantTarget = body.qdrant_target || {};

// Validate required
if (!sourceId) errors.push('source_id requis');
if (!tenantId) errors.push('tenant_id requis');
if (!guildId) errors.push('guild_id requis');
if (!botId) errors.push('bot_id requis');
if (active === undefined || active === null) errors.push('active requis');
if (!fileType) errors.push('file_type requis');

// File source validation
if (!b2FileKey && !url) {
  errors.push('b2_file_key ou url requis');
}

// Callback URLs validation
if (!callbackUrls.progress || !callbackUrls.complete || !callbackUrls.error) {
  errors.push('callback_urls.{progress,complete,error} requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    source_id: sourceId
  };
}

// Extract Qdrant config (with fallback to env)
const qdrantConfig = {
  host: qdrantTarget.host || process.env.QDRANT_SHARED_1_HOST || 'host3.local',
  port: qdrantTarget.port || process.env.QDRANT_SHARED_1_PORT || 20001,
  api_key: qdrantTarget.api_key || process.env.QDRANT_SHARED_1_API_KEY || ''
};

return {
  valid: true,
  source_id: sourceId,
  tenant_id: tenantId,
  guild_id: guildId,
  bot_id: botId,
  active: active,
  file_type: fileType,
  b2_file_key: b2FileKey,
  url: url,
  extraction_method: extractionMethod,
  title: title,
  lang: lang,
  callback_urls: callbackUrls,
  qdrant: qdrantConfig,
  start_time: Date.now()
};

// ============================================
// CALLBACK PROGRESS - Helper function
// ============================================

const ctx = $('Validate Payload').item.json;

return {
  url: ctx.callback_urls.progress,
  body: {
    status: 'pending',
    progress_percent: 10,
    chunk_count: 0
  },
  context: ctx
};

// ============================================
// PLACEHOLDER: EXTRACTION
// TODO: Implement real extraction
// ============================================

const ctx = $('Prepare Callback Start').item.json.context;

// Placeholder extracted text
const extractedText = `[PLACEHOLDER EXTRACTION]\n\nSource: ${ctx.source_id}\nType: ${ctx.file_type}\nMethod: ${ctx.extraction_method}\n\nThis is placeholder text for testing the RAG pipeline.\nReal implementation will fetch and extract content from B2 or URL.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris.`;

return {
  ...ctx,
  extracted_text: extractedText,
  extraction_success: true,
  char_count: extractedText.length
};

// ============================================
// CHUNKING - RFC-099
// ============================================

const ctx = $('Extract Content (PLACEHOLDER)').item.json;
const text = ctx.extracted_text || '';

// Chunking parameters
const CHUNK_SIZE = 1000; // characters
const CHUNK_OVERLAP = 200; // overlap

const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

// Split by paragraphs
const paragraphs = text.split(/\n\n+/);

for (const para of paragraphs) {
  if (currentChunk.length + para.length > CHUNK_SIZE && currentChunk.length > 0) {
    // Save chunk
    chunks.push({
      index: chunkIndex,
      text: currentChunk.trim(),
      char_count: currentChunk.trim().length
    });
    chunkIndex++;

    // Overlap
    const words = currentChunk.split(' ');
    const overlapWords = words.slice(-Math.ceil(CHUNK_OVERLAP / 5));
    currentChunk = overlapWords.join(' ') + '\n\n' + para;
  } else {
    currentChunk += (currentChunk ? '\n\n' : '') + para;
  }
}

// Last chunk
if (currentChunk.trim()) {
  chunks.push({
    index: chunkIndex,
    text: currentChunk.trim(),
    char_count: currentChunk.trim().length
  });
}

return {
  ...ctx,
  chunks: chunks,
  chunk_count: chunks.length
};

// ============================================
// EMBEDDING + QDRANT UPSERT - RFC-099 §5.1
// ============================================

const https = require('https');
const http = require('http');

const ctx = $('Chunk Text').item.json;
const chunks = ctx.chunks || [];

if (chunks.length === 0) {
  throw new Error('No chunks to embed');
}

// ============================================
// STEP 1: EMBED CHUNKS (OpenAI text-embedding-3-small, 1536d)
// ============================================

const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
if (!OPENAI_API_KEY) {
  throw new Error('OPENAI_API_KEY not configured');
}

const BATCH_SIZE = 50; // Max chunks per embedding call
const embeddings = [];

// Batch embedding
for (let i = 0; i < chunks.length; i += BATCH_SIZE) {
  const batch = chunks.slice(i, i + BATCH_SIZE);
  const texts = batch.map(c => c.text);

  const embeddingResponse = await new Promise((resolve, reject) => {
    const data = JSON.stringify({
      input: texts,
      model: 'text-embedding-3-small',
      encoding_format: 'float'
    });

    const options = {
      hostname: 'api.openai.com',
      port: 443,
      path: '/v1/embeddings',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${OPENAI_API_KEY}`,
        'Content-Length': data.length
      }
    };

    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve(JSON.parse(body));
        } else {
          reject(new Error(`OpenAI API error: ${res.statusCode} ${body}`));
        }
      });
    });

    req.on('error', reject);
    req.write(data);
    req.end();
  });

  // Extract embeddings
  for (const item of embeddingResponse.data) {
    embeddings.push(item.embedding);
  }
}

// ============================================
// STEP 2: PREPARE QDRANT CLIENT
// ============================================

const qdrantHost = ctx.qdrant.host;
const qdrantPort = ctx.qdrant.port;
const qdrantApiKey = ctx.qdrant.api_key;
const collectionName = `tenant_${ctx.tenant_id}_default`;

const qdrantRequest = (method, path, body = null) => {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;

    const options = {
      hostname: qdrantHost,
      port: qdrantPort,
      path: path,
      method: method,
      headers: {
        'Content-Type': 'application/json',
        'api-key': qdrantApiKey
      }
    };

    if (data) {
      options.headers['Content-Length'] = data.length;
    }

    const req = http.request(options, (res) => {
      let respBody = '';
      res.on('data', chunk => respBody += chunk);
      res.on('end', () => {
        try {
          const parsed = respBody ? JSON.parse(respBody) : {};
          resolve({ status: res.statusCode, body: parsed });
        } catch (e) {
          resolve({ status: res.statusCode, body: respBody });
        }
      });
    });

    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
};

// ============================================
// STEP 3: CREATE COLLECTION IF NOT EXISTS
// ============================================

const collectionExists = await qdrantRequest('GET', `/collections/${collectionName}`);

if (collectionExists.status === 404) {
  // Create collection
  await qdrantRequest('PUT', `/collections/${collectionName}`, {
    vectors: {
      size: 1536,
      distance: 'Cosine'
    }
  });
}

// ============================================
// STEP 4: UPSERT POINTS WITH 4 IDS (RFC-099 §5.1)
// ============================================

const points = [];

for (let i = 0; i < chunks.length; i++) {
  const chunk = chunks[i];
  const embedding = embeddings[i];

  // Deterministic point ID (RFC-099)
  const pointId = `${ctx.source_id}_chunk_${chunk.index}`;

  points.push({
    id: pointId,
    vector: embedding,
    payload: {
      // Content
      text: chunk.text,
      source_id: ctx.source_id,
      chunk_index: chunk.index,
      title: ctx.title || ctx.source_id,
      source_type: ctx.file_type,
      lang: ctx.lang || 'unknown',

      // 4 IDs d'isolation (CRITIQUES)
      tenant_id: ctx.tenant_id,
      guild_id: ctx.guild_id,
      bot_id: ctx.bot_id,
      active: ctx.active
    }
  });
}

// Upsert with retry (3 attempts, backoff)
let upsertSuccess = false;
let lastError = null;

for (let attempt = 0; attempt < 3; attempt++) {
  try {
    const result = await qdrantRequest('PUT', `/collections/${collectionName}/points`, {
      points: points
    });

    if (result.status === 200) {
      upsertSuccess = true;
      break;
    } else {
      lastError = `Qdrant upsert failed: ${result.status} ${JSON.stringify(result.body)}`;
    }
  } catch (error) {
    lastError = error.message;
  }

  if (attempt < 2) {
    // Backoff: 1s, 2s
    await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
  }
}

if (!upsertSuccess) {
  throw new Error(`Qdrant upsert failed after 3 attempts: ${lastError}`);
}

// ============================================
// RETURN SUCCESS
// ============================================

return {
  ...ctx,
  embedding_success: true,
  qdrant_success: true,
  qdrant_collection: collectionName,
  points_upserted: points.length,
  duration_ms: Date.now() - ctx.start_time
};

// ============================================
// PREPARE CALLBACK COMPLETE
// ============================================

const ctx = $('Embed + Upsert Qdrant').item.json;

return {
  url: ctx.callback_urls.complete,
  body: {
    success: true,
    chunk_count: ctx.chunk_count,
    duration_ms: ctx.duration_ms
  },
  tenant_id: ctx.tenant_id
};
